}

async function main() {
  let address = "mock-address";
  let errorMessage;

  try {
    const { CrossmintWalletsSDK } = await import("@crossmint/wallets-sdk");

    const apiKey = process.env.CROSSMINT_API_KEY;
    const signerSecret = process.env.SIGNER_SECRET;

    if (!apiKey) {
      throw new Error("Missing CROSSMINT_API_KEY environment variable");
    }

    if (!signerSecret) {
      throw new Error("Missing SIGNER_SECRET environment variable");
    }

    const sdk = new CrossmintWalletsSDK({ apiKey });

    const wallet = await sdk.createWallet({
      chain: CHAIN,
      type: TYPE,
      config: {
        recovery: "server",
        signerSecret,
      },
    });

    address =
      wallet?.address ??
      wallet?.wallet?.address ??
      wallet?.data?.address ??
      address;
  } catch (error) {
    errorMessage = error instanceof Error ? error.message : String(error);
  }

  const result = {
    chain: CHAIN,
    type: TYPE,
    address,
  };

  if (errorMessage) {
    result.error = errorMessage;
  }

  await writeResult(result);
}

